-- Authorized six-signature activation; no private-table or other-role grants.
BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
DO $pre$ BEGIN
 PERFORM 1 FROM sgp_lp_afectaciones.config WHERE id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM sgp_lp_afectaciones.config WHERE id AND NOT writes AND NOT physical AND NOT pdt_links AND NOT atomic_pdt) THEN RAISE EXCEPTION 'FLAGS_MUST_BE_OFF'; END IF;
 IF (SELECT md5(prosrc) FROM pg_proc WHERE oid=to_regprocedure('sgp_pdt_multiorigen.registrar(text,text,jsonb,jsonb,uuid,uuid)')) IS DISTINCT FROM 'd1195cca8c35315007969da936979546' THEN RAISE EXCEPTION 'OPTIONAL_NC_CONTRACT_REQUIRED'; END IF;
 IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'sgp_lp_afectaciones_%' AND p.prosecdef AND p.proconfig=ARRAY['search_path=""'] AND pg_get_userbyid(p.proowner)=current_user)<>7 THEN RAISE EXCEPTION 'API_CONTRACT_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='public' AND p.proname LIKE 'sgp_lp_afectaciones_%' AND a.grantee NOT IN(p.proowner,(SELECT oid FROM pg_roles WHERE rolname='anon'))) THEN RAISE EXCEPTION 'UNEXPECTED_API_ACL'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset($api$[{"md5":"eb76d71efb658c4c9d67dda2c2b62a4a","signature":"public.sgp_lp_afectaciones_aluminio_v1(text,text,text,date,integer,jsonb,jsonb)"},{"md5":"a5fdfb67d341a2d8f788b8e0ad34bfbd","signature":"public.sgp_lp_afectaciones_comando_v1(text,text,text,date,integer,jsonb)"},{"md5":"16e1eb3578e56d5d8067ac0d3ca37efb","signature":"public.sgp_lp_afectaciones_conciliar_v1(text,text,text,uuid,text,bigint,jsonb,text)"},{"md5":"22276d883423e5f3dcc32d335f61ee5f","signature":"public.sgp_lp_afectaciones_consultar_v1(text,text,text)"},{"md5":"31a9538446f1cb9b59c46161a60d6861","signature":"public.sgp_lp_afectaciones_consultar_v2(text,text,text)"},{"md5":"5c28c17decfa750376fa32c4fa94ab25","signature":"public.sgp_lp_afectaciones_desde_picking_v1(text,text,text,date,integer,jsonb,uuid)"},{"md5":"ed4534939f9f0a867ad8a6549ab614ec","signature":"public.sgp_lp_afectaciones_legado_v1(text,text,text)"}]$api$::jsonb) expected(signature text,md5 text) LEFT JOIN pg_proc p ON p.oid=to_regprocedure(expected.signature) WHERE p.oid IS NULL OR md5(p.prosrc)<>expected.md5 OR NOT p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[] OR pg_get_userbyid(p.proowner)<>current_user) THEN RAISE EXCEPTION 'API_BODY_OR_SECURITY_DRIFT';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='public' AND p.proname LIKE 'sgp_lp_afectaciones_%' AND a.grantee NOT IN(p.proowner,(SELECT oid FROM pg_roles WHERE rolname='anon'))) THEN RAISE EXCEPTION 'UNEXPECTED_API_ACL';END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN('anon','authenticated','service_role') AND (has_schema_privilege(r.oid,'sgp_lp_afectaciones','USAGE') OR has_schema_privilege(r.oid,'sgp_lp_afectaciones','CREATE'))) THEN RAISE EXCEPTION 'PRIVATE_SCHEMA_EXPOSED';END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='sgp_lp_afectaciones' AND c.relkind IN('r','p') AND (NOT c.relrowsecurity OR a.grantee<>c.relowner)) THEN RAISE EXCEPTION 'PRIVATE_TABLE_EXPOSED';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='sgp_lp_afectaciones' AND a.grantee<>p.proowner) THEN RAISE EXCEPTION 'PRIVATE_FUNCTION_EXPOSED';END IF;
END $pre$;
GRANT EXECUTE ON FUNCTION public.sgp_lp_afectaciones_consultar_v2(text,text,text),
 public.sgp_lp_afectaciones_legado_v1(text,text,text) TO anon;
COMMIT;
